package build

// shared_proxy_sink.go — the Sink a fronted project's nginx site writers use in
// shared-proxy mode.
//
// Purpose: three writers put site confs into the owner's nginx/sites (the
// route generator, plugin route injection and the api-docs conf). In shared
// mode each file must be named `<project>.<file>`, carry the marker
// `# Generated by nself build (project <PROJECT_NAME>)`, use container-name
// upstreams, and be recorded for the registration. This wrapper does that in
// one place, so no writer changes.
// Inputs: the inner Sink and the sharedProxy plan.
// Outputs: writes to the owner's sites dir land under the prefixed name; every
// other path passes through untouched.
// Constraints: only paths directly in the owner's nginx/sites are rewritten.
// ReadDir hides this project's own earlier files, so a rebuild does not report
// a server-name conflict with itself.

import (
	"io/fs"
	"path/filepath"
	"strings"

	"github.com/nself-org/cli/internal/nginx/routemodel"
)

// sharedSink wraps a Sink for one fronted project.
type sharedSink struct {
	Sink
	sp *sharedProxy
}

// sharedMarker is the first line of every conf a fronted project writes.
func sharedMarker(project string) string {
	return nginxGeneratedMarker + " (project " + project + ")"
}

// inSites reports whether p is a path directly inside the owner's sites dir.
func (w *sharedSink) inSites(p string) bool {
	if abs, err := filepath.Abs(p); err == nil {
		p = abs
	}
	return filepath.Clean(filepath.Dir(p)) == w.sp.sitesDir
}

// prefixed returns the on-disk name for file name.
func (w *sharedSink) prefixed(name string) string {
	if strings.HasPrefix(name, w.sp.project+".") {
		return name
	}
	return w.sp.project + "." + name
}

// target maps a path in the sites dir to its prefixed path.
func (w *sharedSink) target(p string) string {
	return filepath.Join(w.sp.sitesDir, w.prefixed(filepath.Base(p)))
}

// body rewrites a conf: container-name upstreams and the project marker.
func (w *sharedSink) body(data []byte) []byte {
	text := string(data)
	if first, rest, ok := strings.Cut(text, "\n"); ok && strings.HasPrefix(first, nginxGeneratedMarker) {
		text = sharedMarker(w.sp.project) + "\n" + rest
	} else if !ok && strings.HasPrefix(first, nginxGeneratedMarker) {
		text = sharedMarker(w.sp.project) + "\n"
	} else {
		text = sharedMarker(w.sp.project) + "\n" + text
	}
	text = routemodel.QualifyText(text, w.sp.qualify)
	// One http{} context: names a snippet declares must not repeat across projects.
	return []byte(routemodel.PrefixDeclared(text, w.sp.project+"_"))
}

// record notes a written conf and the certificate directories it references.
func (w *sharedSink) record(path string, data []byte) {
	w.sp.files["nginx/sites/"+filepath.Base(path)] = true
	for _, g := range certDirRE.FindAllStringSubmatch(string(data), -1) {
		w.sp.certDirs[g[1]] = true
	}
	for _, n := range confServerNames(string(data)) {
		w.sp.written[n] = true
	}
}

func (w *sharedSink) WriteFile(p string, data []byte, perm fs.FileMode) error {
	if !w.inSites(p) {
		return w.Sink.WriteFile(p, data, perm)
	}
	data, p = w.body(data), w.target(p)
	w.record(p, data)
	return w.Sink.WriteFile(p, data, perm)
}

func (w *sharedSink) WriteAtomic(p string, data []byte, perm fs.FileMode) error {
	if !w.inSites(p) {
		return w.Sink.WriteAtomic(p, data, perm)
	}
	data, p = w.body(data), w.target(p)
	w.record(p, data)
	return w.Sink.WriteAtomic(p, data, perm)
}

func (w *sharedSink) Remove(p string) error {
	if w.inSites(p) {
		p = w.target(p)
	}
	return w.Sink.Remove(p)
}

func (w *sharedSink) ReadDir(p string) ([]fs.DirEntry, error) {
	entries, err := w.Sink.ReadDir(p)
	if err != nil || !w.inSites(filepath.Join(p, "x")) {
		return entries, err
	}
	kept := entries[:0:0]
	for _, e := range entries {
		if !strings.HasPrefix(e.Name(), w.sp.project+".") {
			kept = append(kept, e)
		}
	}
	return kept, nil
}
